// Some portions generated by Codex

const test = require('node:test');
const assert = require('node:assert/strict');
const { loadApi, settle } = require('./query-load-more-harness.js');

function progress(count, elapsed, values = {}) {
    return { type: 'progress', values: Object.assign({
        'result-evaluated-count': count,
        'query-elapsed-ms': elapsed,
        'query-result-status': 'evaluating'
    }, values) };
}

function completed(total, elapsed, offset = 0, loaded = 2) {
    return { type: 'end', metadata: {
        'result-offset': offset,
        'result-limit': 2,
        'result-batch-count': loaded,
        'result-has-more': offset + loaded < total,
        'result-next-offset': offset + loaded,
        'total-result-count': total,
        'query-elapsed-ms': elapsed,
        'query-result-status': 'completed'
    } };
}

function memoryStore() {
    let rows = [];
    return {
        async append(batch) { rows.push(...batch); return rows.length; },
        async read(start, count) { return rows.slice(start, start + count); },
        async count() { return rows.length; },
        async truncate(count) { rows.length = count; return rows.length; },
        async dispose() { rows = []; }
    };
}

test('progress records may precede variables and do not count as loaded rows', () => {
    const { api } = loadApi();
    const state = new api.QueryResultState();
    state.accept({ type: 'head', version: 1 });
    state.accept({ type: 'view', id: 'tuple' });
    state.accept(progress(0, 0));
    assert.equal(state.rowCount, 0);
    assert.equal(state.complete, false);

    state.accept({ type: 'vars', values: ['value'] });
    state.accept({ type: 'rows', values: [
        [{ kind: 'literal', value: 'first' }],
        [{ kind: 'literal', value: 'second' }]
    ] });
    state.accept(progress(10, 3000));
    assert.equal(state.rowCount, 2);
    assert.equal(state.complete, false);

    state.accept(completed(12, 4500));
    assert.equal(state.complete, true);
    assert.equal(state.terminalMetadata['total-result-count'], 12);
    assert.equal(state.terminalMetadata['query-elapsed-ms'], 4500);
});

test('progress records reject invalid, regressing, or exact-total metadata', () => {
    const { api } = loadApi();
    const invalid = [
        progress(undefined, 3000),
        progress(-1, 3000),
        progress(1.5, 3000),
        progress(2, -1),
        progress(2, 3000.5),
        progress(2, 3000, { 'query-result-status': 'completed' }),
        progress(2, 3000, { 'total-result-count': 12 })
    ];
    for (const record of invalid) {
        const state = new api.QueryResultState();
        state.accept({ type: 'view', id: 'tuple' });
        assert.throws(() => state.accept(record), /progress/i);
    }

    const state = new api.QueryResultState();
    state.accept({ type: 'view', id: 'tuple' });
    state.accept(progress(2, 3000));
    assert.throws(() => state.accept(progress(1, 4000)), /progress|monotonic/i);
    assert.throws(() => state.accept(progress(3, 2999)), /progress|monotonic/i);
});

test('terminal records cannot contradict the loaded window or previously reported progress', async () => {
    const { api, document } = loadApi();

    async function rejectWindowTerminal(offset, total, hasMore) {
        const target = document.createElement('section');
        document.body.appendChild(target);
        const renderer = new api.QueryResultRenderer(target, {
            batched: true,
            requestedOffset: offset,
            requestedLimit: 2,
            maxDomRows: 8,
            onLoadMore() {},
            rowStore: memoryStore()
        });
        renderer.beginBatch(offset);
        await renderer.accept({ type: 'head', version: 1 });
        await renderer.accept({ type: 'view', id: 'tuple' });
        await renderer.accept({ type: 'vars', values: ['value'] });
        await renderer.accept({ type: 'rows', values: [
            [{ kind: 'literal', value: 'first' }],
            [{ kind: 'literal', value: 'second' }]
        ] });
        const end = completed(total, 4000, offset, 2);
        end.metadata['result-has-more'] = hasMore;
        await assert.rejects(renderer.accept(end), /exact total|continuation metadata/i);
        renderer.dispose();
    }

    await rejectWindowTerminal(4, 5, false);
    await rejectWindowTerminal(0, 12, false);

    const regressedCount = new api.QueryResultState();
    regressedCount.accept({ type: 'view', id: 'tuple' });
    regressedCount.accept({ type: 'vars', values: ['value'] });
    regressedCount.accept({ type: 'rows', values: [[{ kind: 'literal', value: 'row' }]] });
    regressedCount.accept(progress(10, 3000));
    assert.throws(() => regressedCount.accept(completed(9, 3500)), /exact total|progress|completion/i);

    const regressedElapsed = new api.QueryResultState();
    regressedElapsed.accept({ type: 'view', id: 'tuple' });
    regressedElapsed.accept({ type: 'vars', values: ['value'] });
    regressedElapsed.accept({ type: 'rows', values: [[{ kind: 'literal', value: 'row' }]] });
    regressedElapsed.accept(progress(10, 3000));
    assert.throws(() => regressedElapsed.accept(completed(12, 2500)), /progress|completion/i);
});

test('renderer shows the running time while busy and leaves the final time to the status', async () => {
    const { api, document, window } = loadApi();
    const ticks = [];
    window.setTimeout = callback => ticks.push(callback);
    window.clearTimeout = () => {};
    let now = 10000;
    const target = document.createElement('section');
    document.body.appendChild(target);
    const renderer = new api.QueryResultRenderer(target, {
        batched: true,
        requestedOffset: 0,
        requestedLimit: 2,
        maxDomRows: 8,
        onLoadMore() {},
        rowStore: memoryStore(),
        now: () => now
    });

    renderer.beginBatch(0);
    renderer.setBusy(true);
    assert.equal(renderer.timer.hidden, false);
    assert.equal(renderer.timer.getAttribute('role'), 'timer');
    assert.equal(renderer.timer.textContent, '0.0 s');
    now += 1500;
    ticks.shift()();
    assert.equal(renderer.timer.textContent, '1.5 s', 'the running time ticks while the query runs');

    await renderer.accept({ type: 'head', version: 1 });
    await renderer.accept({ type: 'view', id: 'tuple' });
    await renderer.accept({ type: 'vars', values: ['value'] });
    await renderer.accept({ type: 'rows', values: [
        [{ kind: 'literal', value: 'first' }],
        [{ kind: 'literal', value: 'second' }]
    ] });
    await renderer.accept(progress(10, 3000));
    assert.equal(renderer.timer.textContent, '3.0 s', 'the elapsed time reported by the server sets the running time');
    assert.doesNotMatch(renderer.status.textContent, /elapsed/, 'the timer, not the status line, shows the time');

    await renderer.accept(completed(12, 4500));
    renderer.setBusy(false);
    await settle();
    assert.match(renderer.status.textContent, /· complete in 4,500 ms$/);
    assert.equal(renderer.timer.hidden, true, 'the status line reports the final time');

    renderer.beginBatch(2);
    renderer.setBusy(true);
    now += 2000;
    renderer.fail('Query cancelled.', 'cancelled');
    renderer.setBusy(false);
    assert.equal(renderer.timer.hidden, false);
    assert.equal(renderer.timer.textContent, 'after 2.0 s', 'a query that did not complete reports how long it ran');
    renderer.dispose();
});

test('renderer cancels a running query with the warning action', () => {
    const { api, document } = loadApi();
    const target = document.createElement('section');
    document.body.appendChild(target);
    const renderer = new api.QueryResultRenderer(target, {
        batched: true,
        requestedOffset: 0,
        requestedLimit: 2,
        maxDomRows: 8,
        onLoadMore() {},
        rowStore: memoryStore()
    });

    renderer.setBusy(true);

    assert.equal(renderer.cancelButton.hidden, false);
    assert.equal(renderer.cancelButton.textContent, 'Cancel query');
    assert.match(renderer.cancelButton.className, /\bworkbench-action--warning\b/);
    assert.doesNotMatch(renderer.cancelButton.className, /\bworkbench-action--secondary\b/);
    assert.equal(target.getAttribute('aria-busy'), 'true', 'the busy results show the local progress bar');
});

test('renderer separates loaded rows from processed progress and commits exact totals only at end', async () => {
    const { api, document } = loadApi();
    const target = document.createElement('section');
    document.body.appendChild(target);
    const renderer = new api.QueryResultRenderer(target, {
        batched: true,
        requestedOffset: 0,
        requestedLimit: 2,
        maxDomRows: 8,
        onLoadMore() {},
        rowStore: memoryStore()
    });
    renderer.beginBatch(0);
    renderer.setBusy(true);
    await renderer.accept({ type: 'head', version: 1 });
    await renderer.accept({ type: 'view', id: 'tuple' });
    await renderer.accept({ type: 'vars', values: ['value'] });
    await renderer.accept({ type: 'rows', values: [
        [{ kind: 'literal', value: 'first' }],
        [{ kind: 'literal', value: 'second' }]
    ] });
    await renderer.accept(progress(10, 3000));

    assert.equal(renderer.state.rowCount, 2);
    assert.equal(renderer.state.complete, false);
    assert.match(renderer.status.textContent, /^Receiving… 2 rows/, 'loaded rows are counted in the status line');
    assert.match(renderer.root.textContent, /10.*processed/i);
    assert.match(renderer.root.textContent, /(?:3,?000\s?ms|3(?:\.0+)?\s?(?:s|seconds?))/i);
    assert.equal(renderer.loadMoreButton.disabled, true,
        'continuation remains unavailable until full evaluation reaches its terminal record');

    await renderer.accept(completed(12, 4500));
    renderer.setBusy(false);
    await settle();
    assert.equal(renderer.state.complete, true);
    assert.equal(renderer.state.terminalMetadata['total-result-count'], 12);
    assert.match(renderer.root.textContent, /2.*loaded/i);
    assert.match(renderer.root.textContent, /12/);
    assert.match(renderer.root.textContent, /(?:4,?500\s?ms|4\.5\s?(?:s|seconds?))/i);
    assert.equal(renderer.loadMoreButton.disabled, false);
    assert.equal(renderer.loadMoreButton.hidden, false);

    renderer.beginBatch(2);
    renderer.setBusy(true);
    await renderer.accept({ type: 'head', version: 1 });
    await renderer.accept({ type: 'view', id: 'tuple' });
    await renderer.accept({ type: 'vars', values: ['value'] });
    await renderer.accept({ type: 'rows', values: [[{ kind: 'literal', value: 'third' }]] });
    await renderer.accept(progress(15, 7000));
    await renderer.rollbackBatch('The replay did not complete.', 'incomplete');
    renderer.setBusy(false);
    await settle();

    assert.equal(renderer.state.rowCount, 2);
    assert.equal(renderer.state.complete, true);
    assert.equal(renderer.state.terminalMetadata['total-result-count'], 12,
        'a failed replay retains the last exact total');
    assert.doesNotMatch(renderer.root.textContent, /15.*processed/i,
        'progress from an uncommitted replay is removed with its row tail');
    renderer.dispose();
});
